def squash(s: str) -> str:
    """Compress string `s` into runs as described."""
    if not s:
        return ""

    def esc(ch: str) -> str:
        # Escape digits and backslash.
        if ch.isdigit() or ch == "\\":
            return "\\" + ch
        return ch

    out = []
    i = 0
    n = len(s)
    while i < n:
        j = i + 1
        while j < n and s[j] == s[i]:
            j += 1
        run_len = j - i
        ch = s[i]
        if run_len >= 3:
            out.append(str(run_len))
            out.append(esc(ch))
        else:
            for _ in range(run_len):
                out.append(esc(ch))
        i = j

    return "".join(out)
